 static int Main(string[]args){try{if(args.Length!=2||!Path.IsPathRooted(args[0]))return 2;string[] names=args[1]=="active"?new[]{"active-selection.json"}:args[1]=="registered"?new[]{"dlpad.exe","notice.txt","install-ready.json","install-registration.json","install-registration-seal.json"}:args[1]=="receipt"?new[]{"registration-receipt.json"}:args[1]=="journal"?new[]{"intent.json","prepared.json","registered.json","receipt.json","active.json"}:args[1]=="source"?new[]{"dlpad.exe","notice.txt"}:args[1]=="outer"?new[]{"registered","receipt","active"}:null;if(names==null)return 2;object before=Observe(args[0],true);var entries=new Dictionary<string,object>();var actual=new List<string>();foreach(string entry in Directory.EnumerateFileSystemEntries(args[0])){if(actual.Count>=names.Length)throw new IOException("namespace bound");actual.Add(Path.GetFileName(entry));}actual.Sort(StringComparer.Ordinal);var expected=(string[])names.Clone();Array.Sort(expected,StringComparer.Ordinal);if(actual.Count!=expected.Length)throw new IOException("namespace count");for(int i=0;i<expected.Length;i++)if(actual[i]!=expected[i])throw new IOException("namespace name");foreach(string leaf in names)entries.Add(leaf,Observe(Path.Combine(args[0],leaf),args[1]=="outer",leaf=="dlpad.exe"?134217728:65536));object after=Observe(args[0],true);var json=new JavaScriptSerializer();if(json.Serialize(before)!=json.Serialize(after))throw new IOException("root changed");string output=json.Serialize(new{schema=1,status="OBSERVED_NATIVE_IDS",root=before,entries=entries});if(output.Length>8192)return 2;Console.WriteLine(output);return 0;}catch{Console.WriteLine("{\"status\":\"FAIL\"}");return 1;}}
